-- 自动生成(generate_news_lua.py)，勿手改。插件「资讯」页数据：更新日志(最新3版)/游戏版本/强度榜/关注/频道。
GearInsightNews = {
  builtAt="2026-09-22",
  releases={
    { version="0.92.17", date="2026-09-22", items={
      { zh="逃课清单 09-22：追猎 6 倍今日双地图（永歌森林 46 / 55 + 虚影风暴 43 / 69，限时返场）；丰裕「阿塔阿曼」笛子 + 撞泡泡召青蛙双 Buff。", en="Cheese list 09-22: Hunts x6 on two maps today (Eversong 46 / 55 + Voidstorm 43 / 69, limited-time return); Bountiful Atal'Aman flute + bubble frogs double buff.", tw="逃課清單 09-22：追獵 6 倍今日雙地圖（永歌森林 46 / 55 + 虛影風暴 43 / 69，限時返場）；豐裕「阿塔阿曼」笛子 + 撞泡泡召青蛙雙 Buff。", kind="changed" },
      { zh="支持榜数据刷新到 09-22。", en="Supporter board refreshed to 09-22.", tw="支持榜資料刷新到 09-22。", kind="changed" },
      { zh="GI 爆发宏 / 保命宏改成按专精命名（GI爆发鲜血、GI保命冰霜…）：之前多个专精共用一个名字，切专精后按新专精重新生成正文，把另一个专精的宏覆盖掉了。更新后到键位页点一次「实现到动作条」，旧的「GI爆发宏 / GI保命宏」用「一键清 GI 宏」清掉。", en="GI Burst / Defensive macros are now named per spec (GIBurstBlood, GIDefFrost…): all specs used to share one name, so switching spec regenerated the body and overwrote the other spec's macro. After updating, click 'apply to action bars' once on the Layout page and remove the old 'GI Burst / GI Defensive' with 'clear GI macros'.", tw="GI 爆發巨集 / 保命巨集改成按專精命名（GI爆發鮮血、GI保命冰霜…）：之前多個專精共用一個名字，切專精後按新專精重新生成內文，把另一個專精的巨集覆蓋掉了。更新後到鍵位頁點一次「實現到動作條」，舊的用「一鍵清 GI 巨集」清掉。", kind="fixed" },
    } },
    { version="0.92.16", date="2026-09-21", items={
      { zh="GI 循环助手钉板登录后自动出现：钉过板子且没关掉的，登录 3 秒后自动加载键位模块并把板子放出来，不用再先点开插件界面。", en="The GI rotation board now appears on its own after login: if it was pinned and not closed, the layout module is loaded 3 s after login and the board comes back without opening the addon window.", tw="GI 循環助手釘板登入後自動出現：釘過板子且沒關掉的，登入 3 秒後自動載入鍵位模組並把板子放出來，不用再先點開插件介面。", kind="added" },
      { zh="每天第一次登录自动存一份永久键位备份「每日存档 MM-DD」，不占 6 份永久名额，只保留最近 3 天；变身 / 战斗中会稍后重试。", en="First login each day saves a permanent layout backup named 'Daily backup MM-DD'; it doesn't use a pinned slot and only the last 3 days are kept; retried later if shapeshifted or in combat.", tw="每天第一次登入自動存一份永久鍵位備份「每日存檔 MM-DD」，不佔 6 份永久名額，只保留最近 3 天；變身 / 戰鬥中會稍後重試。", kind="added" },
      { zh="钉板「只看助手」收起态重做：无标题 HUD（标题和按钮悬停才出现），大图标居中带冷却扇形、键帽在角上，技能名和「就绪 / 冷却 x.xs」居中排在下面，就绪时呼吸光，按对了键帽按压 + 图标弹一下；卡片宽度从中间向两边长。", en="Pinned board compact mode redone: a title-less HUD (title and buttons appear on hover), centered big icon with cooldown swipe and corner key cap, spell name and 'Ready / CD x.xs' centered below, glow when ready, key-press + icon pop when you cast it; the card grows from its center.", tw="釘板「只看助手」收起態重做：無標題 HUD（標題和按鈕懸停才出現），大圖示居中帶冷卻扇形、鍵帽在角上，技能名和「就緒 / 冷卻 x.xs」居中排在下面，就緒時呼吸光，按對了鍵帽按壓 + 圖示彈一下；卡片寬度從中間向兩邊長。", kind="changed" },
      { zh="键位页 Shift+左键技能 / 物品格塞进宏编辑器时改为插件自己写行（/cast 技能名、/use 物品名），不再走暴雪链接插入——国服 12.x 那条路会写成「/施放 [技能]」触发「未知的宏设置」；天赋替换后的技能写替换后的名字。", en="Shift+clicking a spell / item cell into the macro editor now writes the line itself (/cast name, /use item) instead of Blizzard's link insert, which on zhCN 12.x produced '/施放 [spell]' and an 'unknown macro option' error; talent-replaced spells use the replacing spell's name.", tw="鍵位頁 Shift+左鍵技能 / 物品格塞進巨集編輯器時改為插件自己寫列（/cast 技能名、/use 物品名），不再走暴雪連結插入；天賦替換後的技能寫替換後的名字。", kind="changed" },
    } },
    { version="0.92.15", date="2026-09-21", items={
      { zh="刷本规划把「同款已穿上」一律算拿到，不看轨道：勇士轨道 308 的套装手套升满也到不了 334，却被标成已齐全、从要刷的清单里消失。现在和总览页同一口径——轨道升满够得着才算有（只差升级），到不了的照常列进「缺」，并提示「要重拿更高难度的同款」；套装件数统计一起改。", en="Farming planner counted any equipped copy of an item as obtained, ignoring its upgrade track: a Champion-track 308 tier glove that tops out below 334 was marked complete and dropped from the farm list. It now matches the overview: owned only if the track can reach the target (just upgrade), otherwise it stays in the 'missing' list with a note to farm a higher-difficulty copy; tier-set counts follow the same rule.", tw="刷本規劃把「同款已穿上」一律算拿到，不看軌道：勇士軌道 308 的套裝手套升滿也到不了 334，卻被標成已齊全、從要刷的清單裡消失。現在和總覽頁同一口徑——軌道升滿夠得著才算有（只差升級），到不了的照常列進「缺」，並提示「要重拿更高難度的同款」；套裝件數統計一起改。", kind="fixed" },
    } },
  },
  patch={ title="12.1 至暗之夜 · 赛季 2 · 热修记录", titleEn="Patch 12.1 Midnight · Season 2 · Hotfixes", source="", hotfixes={
    { date="2026-09-22", lines={ "本周调整主要针对大秘境 / 团本 / PvP 里的弱势专精，并拉平部分英雄天赋差距（蓝贴 9 月 19 日 Linxy）", "鲜血 DK：全部技能与随从伤害 -6%；灵界打击 +25%；致命延伸改为对 2 个目标造成 60%（原 75%）；死亡使者：破灭 +25%、死神印记 +20%、灵魂浪潮 +20%、黑暗之缚使血液沸腾 +50%（原 30%）、致命打击使灵界打击 +20%（原 12%）、凄惨痛快 +15%（原 10%）", "冰霜 DK：掠霜使者伤害 +100%；湮灭 +10%（均不影响 PvP）", "邪恶 DK：腐蚀改为疾病在 65%/100% 时爆发（原 50%/70%）；枯萎凋落改为爆发剩余疾病伤害的 200%（原 100%）；血魔：悲痛之罚使吸血鬼打击爆发效果 +75%（原 30%）、鲜血之悦使恐惧疫病 +20%（原 10%）、疯狂嗜血每层使凋零缠绕与灵界打击 +5%", "恶魔猎手：吞噬者：坍缩之星主目标 +25%、吞噬 +8%（不影响 PvP）；浩劫 / 复仇 奥达奇收割者：战刃艺术增伤 15%/30%（原 10%/20%）、收割者之刃 +25%（复仇 +30%）、收割者印记 +7%（复仇 +8%）、破碎精神碎裂几率 20%（原 15%）", "德鲁伊：荒野追猎者 爆裂生长 +15%、耐心守护者流血 +10%（原 8%）；恢复：全治疗 +4%，修复光合作用被他人 HoT 触发（均不影响 PvP）", "唤魔师：增辉：喷发 +15%、火焰吐息 +60%、地裂 +40%、灼热鳞片 +100%；湮灭：火葬 +10%、不羁之焰 +25%、火焰吐息 +5%、碧蓝打击 +50%、碧蓝横扫 +50%、碎裂之星 +10%（湮灭不影响 PvP）", "猎人：射击：巧射弹射 75%（原 60%）、乱射 +10%；生存：野火炸弹 +20%，主目标额外伤害 50%（原 80%）", "法师：火焰：陨石 DoT +100%（不影响 PvP）、霜火 双重施法 烈焰风暴 +15%（原 10%）、阳炎 力量重担 烈焰风暴 +6%（原 3%）；冰霜：寒冰宝珠 +15%、彗星风暴 +50%（不影响 PvP）、冻伤碎裂溅射 +10%、冰川突袭彗星 +50%", "武僧：织雾：全治疗 +5%、活血术 +15%、神龙之赐 +15%；踏风：普攻 +25%、双重威胁 +20%、旭日东升踢 +8%（均不影响 PvP）", "圣骑士：防护：全技能伤害 +6%（不影响 PvP）；惩戒 圣殿骑士：圣光之锤 +50%（不影响 PvP）、苍穹之锤 +12%", "牧师：戒律：非团本 / 战场副本里救赎治疗 +40%，PvP 中不再 +40%；苦修耗蓝 -20%；暗影：心灵震爆 / 虚空震爆 / 暗言术：灭 / 暗言术：狂 / 精神鞭笞 / 精神鞭笞：狂乱 各 +15%，心灵链接分摊 20%（原 25%），暗影爆发 -5%（部分不影响 PvP）", "盗贼：敏锐 欺诈者：隐秘之刃 +50%、致命一击 +30%（不影响 PvP）", "战士：狂怒 / 防护 山丘领主：闪电打击 +50%、贯地电流 +50%", "PvP：血魔邪 DK 吸血鬼打击 +100%；野德利爪 撕碎 +20%；奶德 迅捷治愈 -20%；增辉 黑檀之力 12%；黑箭 +30%；生存猎 -10%~15%；火法 火焰冲击 160%（原 180%）；踏风 天神之力 +50%、影踪派 疾风连击 -15%；神牧 执政官 光环 +30%；暗牧 暗言术：灭 +30%；刺杀 -4%、狂徒 +5%；元素 闪电箭 +25%、熔岩爆裂 +15%；增强 +3%；痛苦 痛楚 +40%；武器 巨像 熟练打击 40%（原 25%）" }, linesEn={ "This week's pass targets low performers in Mythic+, raid and PvP, and narrows some hero-talent gaps (blue post Sep 19, Linxy)", "Blood DK: all ability and minion damage -6%; Death Strike +25%; Deadly Reach now 60% to 2 nearby (was 75%); Deathbringer: Exterminate +25%, Reaper's Mark +20%, Wave of Souls +20%, Bind in Darkness Blood Boil +50% (was 30%), Deathly Blows Death Strike +20% (was 12%), Swift and Painful Strength +15% (was 10%)", "Frost DK: Frostreaper +100%; Obliterate +10% (both PvE only)", "Unholy DK: Scourging erupts plagues at 65%/100% (was 50%/70%); Blightfall deals 200% of remaining plague damage (was 100%); San'layn: Infliction of Sorrow +75% (was 30%), Thrill of Blood Dread Plague +20% (was 10%), Frenzied Bloodthirst now +5% Death Coil / Death Strike per stack", "Demon Hunter: Devourer Collapsing Star primary +25%, Consume/Devour +8% (PvE); Havoc / Vengeance Aldrachi Reaver: Art of the Glaive 15%/30% (was 10%/20%), Reaver's Glaive +25% (Vengeance +30%), Reaver's Mark 7% (Vengeance 8%), Broken Spirit 20% (was 15%)", "Druid: Wildstalker Bursting Growth +15%, Patient Custodian bleeds +10% (was 8%); Restoration all healing +4%, Photosynthesis no longer triggers from others' HoTs (PvE)", "Evoker: Augmentation Eruption +15%, Fire Breath +60%, Upheaval +40%, Blistering Scales +100%; Devastation Pyre +10%, Unbound Flame +25%, Fire Breath +5%, Azure Strike +50%, Azure Sweep +50%, Shattering Star +10% (PvE)", "Hunter: Marksmanship Trick Shots ricochet 75% (was 60%), Volley +10%; Survival Wildfire Bomb +20%, primary-target bonus 50% (was 80%)", "Mage: Fire Meteor DoT +100% (PvE), Frostfire Dualcasting Adept Flamestrike +15% (was 10%), Sunfury Burden of Power Flamestrike +6% (was 3%); Frost Frozen Orb +15%, Comet Storm +50% (PvE), Frostbite shatter +10%, Glacial Assault comet +50%", "Monk: Mistweaver all healing +5%, Vivify +15%, Sheilun's Gift +15%; Windwalker auto-attack +25%, Dual Threat +20%, Rising Sun Kick +8% (all PvE)", "Paladin: Protection all ability damage +6% (PvE); Retribution Templar Hammer of Light +50% (PvE), Empyrean Hammer +12%", "Priest: Discipline Atonement +40% outside raid / battleground instances, no longer +40% in PvP; Penance mana -20%; Shadow Mind Blast / Void Blast / SW:Death / SW:Madness / Mind Flay / Mind Flay: Insanity +15%, Psychic Link 20% (was 25%), Shadeburst -5%", "Rogue: Subtlety Trickster Unseen Blade +50%, Coup de Grace +30%